import sys
sys.setrecursionlimit(10000)

def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    cache = {}
    state = set()

    def parse_cell_name(name):
        col_str = ""
        row_str = ""
        for c in name:
            if c.isalpha(): col_str += c
            else: row_str += c
        col_idx = 0
        for c in col_str:
            col_idx = col_idx * 26 + (ord(c) - ord('A'))
        return col_idx, int(row_str)

    def col_to_name(idx):
        res = ""
        idx += 1
        while idx > 0:
            idx, rem = divmod(idx, 26)
            res = chr(ord('A') + rem - 1) + res
        return res

    class Parser:
        def __init__(self, text):
            self.s = text.replace(" ", "")
            self.pos = 0
            self.n = len(self.s)
        def peek(self):
            return self.s[self.pos] if self.pos < self.n else ""
        def advance(self):
            self.pos += 1
        def parse(self):
            return self.parse_expr()
        def parse_expr(self):
            left = self.parse_term()
            while self.peek() in "+-":
                op = self.peek()
                self.advance()
                right = self.parse_term()
                left = ("BIN", op, left, right)
            return left
        def parse_term(self):
            left = self.parse_factor()
            while self.peek() in "*/":
                op = self.peek()
                self.advance()
                right = self.parse_factor()
                left = ("BIN", op, left, right)
            return left
        def parse_factor(self):
            if self.peek() == "-":
                self.advance()
                return ("UNARY_MINUS", self.parse_factor())
            return self.parse_atom()
        def parse_atom(self):
            tok = self.peek()
            if tok.isalpha():
                name = ""
                while self.peek().isalpha():
                    name += self.peek()
                    self.advance()
                if self.peek().isdigit():
                    while self.peek().isdigit():
                        name += self.peek()
                        self.advance()
                    return ("CELL", name)
                elif self.peek() == '(':
                    return self.parse_function_call(name)
                else:
                    return ("CELL", name)
            elif tok == "(":
                self.advance()
                expr = self.parse_expr()
                if self.peek() == ")":
                    self.advance()
                return expr
            elif tok.isdigit():
                num = ""
                while self.peek().isdigit():
                    num += self.peek()
                    self.advance()
                return ("NUM", int(num))
            else:
                return ("NUM", 0)
        def parse_function_call(self, name):
            self.advance()
            args = []
            if name.upper() == "IF":
                left = self.parse_expr()
                op = self.peek()
                self.advance()
                if self.peek() == "=":
                    op += self.peek()
                    self.advance()
                right = self.parse_expr()
                args = [("CMP", op, left, right)]
                if self.peek() == ",": self.advance()
                args.append(self.parse_expr())
                if self.peek() == ",": self.advance()
                args.append(self.parse_expr())
            else:
                if self.peek() != ')':
                    args = self.parse_args()
            if self.peek() == ")":
                self.advance()
            return ("FUNC", name, args)
        def parse_args(self):
            args = []
            while self.peek() != ")":
                args.append(self.parse_arg())
                if self.peek() == ",":
                    self.advance()
            return args
        def parse_arg(self):
            tok = self.peek()
            if tok.isalpha() and self.is_range_start():
                start = self.parse_cell_ref()
                self.advance()
                end = self.parse_cell_ref()
                return ("RANGE", start[1], end[1])
            else:
                return self.parse_expr()
        def parse_cell_ref(self):
            name = ""
            while self.peek().isalpha():
                name += self.peek()
                self.advance()
            while self.peek().isdigit():
                name += self.peek()
                self.advance()
            return ("CELL", name)
        def is_range_start(self):
            if self.pos >= self.n: return False
            if not self.s[self.pos].isalpha(): return False
            i = self.pos + 1
            while i < self.n and self.s[i].isdigit(): i += 1
            if i >= self.n: return False
            if self.s[i] == ':': return True
            return False

    def eval_node(node):
        typ = node[0]
        if typ == "NUM":
            return node[1]
        elif typ == "CELL":
            name = node[1]
            if name not in cells:
                return 0
            if name in cache:
                return cache[name]
            if name in state:
                return "#CYCLE!"
            state.add(name)
            res = eval_content(cells[name])
            cache[name] = res
            state.discard(name)
            return res
        elif typ == "BIN":
            _, op, left, right = node
            l_val = eval_node(left)
            if isinstance(l_val, str): return l_val
            r_val = eval_node(right)
            if isinstance(r_val, str): return r_val
            if op == "+": return l_val + r_val
            if op == "-": return l_val - r_val
            if op == "*": return l_val * r_val
            if op == "/":
                if r_val == 0: return "#DIV/0!"
                if (l_val < 0) ^ (r_val < 0):
                    return -((-l_val) // r_val)
                else:
                    return l_val // r_val
        elif typ == "UNARY_MINUS":
            val = eval_node(node[1])
            return -val if isinstance(val, int) else val
        elif typ == "FUNC":
            _, fname, args = node
            if fname.upper() == "IF":
                cond = eval_node(args[0])
                if isinstance(cond, str): return cond
                if cond:
                    return eval_node(args[1])
                else:
                    return eval_node(args[2])
            else:
                eval_args = []
                for arg in args:
                    val = eval_node(arg)
                    if isinstance(val, str): return val
                    eval_args.append(val)
                vals = []
                for v in eval_args:
                    if isinstance(v, list): vals.extend(v)
                    else: vals.append(v)
                if fname.upper() == "SUM":
                    return sum(vals) if vals else 0
                if fname.upper() == "MIN":
                    return min(vals) if vals else 0
                if fname.upper() == "MAX":
                    return max(vals) if vals else 0
        elif typ == "RANGE":
            _, c1, c2 = node
            col1, row1 = parse_cell_name(c1)
            col2, row2 = parse_cell_name(c2)
            min_col, max_col = min(col1, col2), max(col1, col2)
            min_row, max_row = min(row1, row2), max(row1, row2)
            res = []
            for r in range(min_row, max_row + 1):
                for c in range(min_col, max_col + 1):
                    name = col_to_name(c) + str(r)
                    if name in cells:
                        val = eval_node(("CELL", name))
                        if isinstance(val, str): return val
                        res.append(val)
            return res
        elif typ == "CMP":
            _, op, left, right = node
            l_val = eval_node(left)
            if isinstance(l_val, str): return l_val
            r_val = eval_node(right)
            if isinstance(r_val, str): return r_val
            if op == "=": return 1 if l_val == r_val else 0
            if op == "<>": return 1 if l_val != r_val else 0
            if op == "<": return 1 if l_val < r_val else 0
            if op == "<=": return 1 if l_val <= r_val else 0
            if op == ">": return 1 if l_val > r_val else 0
            if op == ">=": return 1 if l_val >= r_val else 0

    def eval_content(text):
        if text.startswith("="):
            text = text[1:]
        p = Parser(text)
        tree = p.parse()
        return eval_node(tree)

    result = {}
    for name in cells:
        if name not in cache:
            result[name] = eval_content(cells[name])
        else:
            result[name] = cache[name]
    return result
